using Game.Shared.Enums;

namespace Game.Server.Configuration;

public sealed class MonsterCombatOptions
{
    public const string SectionName = "MonsterCombat";
    public List<BattleStatusOptions> StatusEffects { get; set; } = [];
    public List<MonsterSkillOptions> Skills { get; set; } = [];
    public Dictionary<string, MonsterCombatProfileOptions> Profiles { get; set; } =
        new(StringComparer.OrdinalIgnoreCase);
    public Dictionary<string, List<MonsterDepthStageOptions>> DepthProgressions { get; set; } =
        new(StringComparer.OrdinalIgnoreCase);
}

public sealed class BattleStatusOptions
{
    public string Code { get; set; } = string.Empty;
    public string Name { get; set; } = string.Empty;
    public string Description { get; set; } = string.Empty;
    public string EffectType { get; set; } = string.Empty;
    public decimal ValuePerStack { get; set; }
    public int MaxStacks { get; set; } = 1;
    public string Stacking { get; set; } = "RefreshDuration";
    public bool IsPositive { get; set; }
    public bool IsDispellable { get; set; } = true;
    public bool IsHidden { get; set; }
    public BattleStatusLifetime Lifetime { get; set; }
    public BattleStatusCounterKind CounterKind { get; set; }
    public BattleStatusMechanic Mechanic { get; set; }
    public BattleStatusSnapshotRefresh SnapshotRefresh { get; set; }
    public string? FamilyCode { get; set; }
    public BattleStatusFamilyRefresh FamilyRefresh { get; set; }
    public int InitialStacks { get; set; } = 1;
    public int MechanicLevel { get; set; }
    public decimal MechanicPower { get; set; }
}

public sealed class MonsterSkillOptions
{
    public string Code { get; set; } = string.Empty;
    public string Name { get; set; } = string.Empty;
    public string Description { get; set; } = string.Empty;
    public string TargetType { get; set; } = "Front";
    public List<CombatSkillEffectOptions>? Effects { get; set; }
    public int InitialCooldownRounds { get; set; }
    public int DamagePowerPercent { get; set; }
    public int CooldownRounds { get; set; }
    public int? SelfHpBelowPercent { get; set; }
    public int? RoomRoundAtLeast { get; set; }
    public int ForcedPriority { get; set; }
    public bool IsInterruptible { get; set; } = true;
    public string DangerLevel { get; set; } = "Normal";
    public List<MonsterStatusApplicationOptions> Statuses { get; set; } = [];
}

public sealed class MonsterStatusApplicationOptions
{
    public string StatusCode { get; set; } = string.Empty;
    public int DurationRounds { get; set; }
}

public sealed class MonsterCombatProfileOptions
{
    public int SkillUseChancePercent { get; set; }
    // Opt in so existing profiles and frozen room snapshots keep their original clock.
    public bool UseEncounterLocalSkillClock { get; set; }
    public List<MonsterProfileSkillOptions> Skills { get; set; } = [];
    public string? DepthProgressionCode { get; set; }
    public FireCoreOptions? FireCore { get; set; }
    public DeepColdOptions? DeepCold { get; set; }
    public EarthArmorOptions? EarthArmor { get; set; }
    public StaticFieldOptions? StaticField { get; set; }
    public ReflectionMirrorOptions? ReflectionMirror { get; set; }
    public PlaguePoisonOptions? PlaguePoison { get; set; }
}

public sealed class PlaguePoisonOptions
{
    public int TriggerHpPercent { get; set; }
    public int WindowRounds { get; set; }
    public decimal BreakLightDamagePercent { get; set; }
    public decimal AttackPercentPerStack { get; set; }
    public string PoisonStatusCode { get; set; } = string.Empty;
    public string TargetStatusCode { get; set; } = string.Empty;
    public string TickUsedStatusCode { get; set; } = string.Empty;
    public string RewardStatusCode { get; set; } = string.Empty;
    public int RewardRounds { get; set; }
    public List<string> BasicPoisonStatusCodes { get; set; } = [];
    // Missing linkage keeps frozen LV2 rooms at ordinary four-round poison.
    public int ErosionStartStacks { get; set; }
    public decimal ErosionPercentPerStack { get; set; }
    public string ErosionStatusCode { get; set; } = string.Empty;
    public int LethalStacks { get; set; }
}

public sealed class ReflectionMirrorOptions
{
    // LV2/LV3 keep one HP trigger; LV4 follows the persistent encounter-local schedule.
    public int? TriggerHpPercent { get; set; }
    public int FirstActivationRound { get; set; }
    public int CycleRounds { get; set; }
    public int WindowRounds { get; set; }
    public int InitialStacks { get; set; }
    public ElementType RemovalElement { get; set; } = ElementType.Dark;
    public decimal ReflectPercentPerStack { get; set; }
    public decimal MaxHpCapPercentPerStack { get; set; }
    public string MirrorStatusCode { get; set; } = string.Empty;
    public string HitUsedStatusCode { get; set; } = string.Empty;
    public string BudgetStatusCode { get; set; } = string.Empty;
    public string RewardStatusCode { get; set; } = string.Empty;
    public int RewardRounds { get; set; }
    // Optional LV3 linkage. Missing fields keep frozen LV2 rooms at fixed reflection strength.
    public int GrowthRounds { get; set; }
    public decimal ReflectGrowthPercentPerStack { get; set; }
    public decimal MaxHpCapGrowthPercentPerStack { get; set; }
    public string AmplificationStatusCode { get; set; } = string.Empty;
}

public sealed class StaticFieldOptions
{
    // LV2/LV3 retain a one-shot HP trigger; LV4 uses a fixed encounter-local schedule.
    public int? TriggerHpPercent { get; set; }
    public int FirstActivationRound { get; set; }
    public int CycleRounds { get; set; }
    public ElementType RemovalElement { get; set; } = ElementType.Fire;
    public int WindowRounds { get; set; }
    public int InitialStacks { get; set; }
    public int GrowthRounds { get; set; }
    public int GrowthStacksPerRound { get; set; }
    public string StaticStatusCode { get; set; } = string.Empty;
    public string HitUsedStatusCode { get; set; } = string.Empty;
    public string GrowthUsedStatusCode { get; set; } = string.Empty;
    public string AmplifiedSkillCode { get; set; } = string.Empty;
    public decimal SkillDamagePercentPerStack { get; set; }
    public string RewardStatusCode { get; set; } = string.Empty;
    public int RewardRounds { get; set; }
    // LV3 optional linkage. Missing fields preserve existing LV2 frozen rooms.
    public int ThunderAtStacks { get; set; }
    public string ThunderSkillCode { get; set; } = string.Empty;
    public string ThunderPendingStatusCode { get; set; } = string.Empty;
}

public sealed class EarthArmorOptions
{
    // LV2/LV3: one HP trigger. LV4: a fixed encounter-local schedule instead.
    public int? TriggerHpPercent { get; set; }
    public int FirstActivationRound { get; set; }
    public int CycleRounds { get; set; }
    public int WindowRounds { get; set; }
    public decimal BreakWindDamagePercent { get; set; }
    public string ArmorStatusCode { get; set; } = string.Empty;
    public string RewardStatusCode { get; set; } = string.Empty;
    public int RewardRounds { get; set; }
    // LV3 optional linkage: armor-round ends build persistent attack stacks; a break clears them.
    public string ResonanceStatusCode { get; set; } = string.Empty;
}

public sealed class DeepColdOptions
{
    public int? TriggerHpPercent { get; set; }
    public int FirstActivationRound { get; set; }
    public int CycleRounds { get; set; }
    // Frozen water rooms authored before attribute alignment retain Fire when the field is absent.
    public ElementType RemovalElement { get; set; } = ElementType.Fire;
    public int WindowRounds { get; set; }
    public int InitialStacks { get; set; }
    public int RewardRounds { get; set; }
    public string ColdStatusCode { get; set; } = string.Empty;
    public string FieldStatusCode { get; set; } = string.Empty;
    public string WarmStatusCode { get; set; } = string.Empty;
    public string PendingStatusCode { get; set; } = string.Empty;
    public string ClearedStatusCode { get; set; } = string.Empty;
    public string MeltUsedStatusCode { get; set; } = string.Empty;
    public List<string> BasicColdStatusCodes { get; set; } = [];
    public int GrowthStacksPerRound { get; set; }
    public int FreezeAtStacks { get; set; }
    public string FreezeStatusCode { get; set; } = string.Empty;
    public string FreezePendingStatusCode { get; set; } = string.Empty;
    public string FreezeUsedStatusCode { get; set; } = string.Empty;
    public string GrowthUsedStatusCode { get; set; } = string.Empty;
}

public sealed class FireCoreOptions
{
    // When set, activate once at the next player-round start at or below this HP percentage.
    public int? TriggerHpPercent { get; set; }
    public int FirstActivationRound { get; set; }
    public int CycleRounds { get; set; }
    public int WindowRounds { get; set; }
    public decimal BreakWaterDamagePercent { get; set; }
    public string HeatingStatusCode { get; set; } = string.Empty;
    public string RewardStatusCode { get; set; } = string.Empty;
    public int RewardRounds { get; set; }
    public string LinkedSkillCode { get; set; } = string.Empty;
    public int ExtraTargetCount { get; set; }
    public int ExtraAttackPowerPercent { get; set; }
}

public sealed class MonsterDepthStageOptions
{
    public int Depth { get; set; }
    public string? ReplacementProfileCode { get; set; }
    public List<MonsterProfileSkillOptions> AddedSkills { get; set; } = [];
}

public sealed class MonsterProfileSkillOptions
{
    public string Code { get; set; } = string.Empty;
    public int Weight { get; set; } = 1;
}

using Game.Server.Configuration;
using System.Collections.Immutable;
using System.Text.Json;
using Microsoft.Extensions.Options;

namespace Game.Server.Services;

public sealed class MonsterCombatCatalog
{
    public BattleStatusCatalog Statuses { get; }
    private readonly Dictionary<string, MonsterSkillOptions> _skills = new(StringComparer.OrdinalIgnoreCase);
    private readonly Dictionary<string, MonsterCombatProfileOptions> _profiles = new(StringComparer.OrdinalIgnoreCase);
    private readonly Dictionary<string, MonsterSkillDefinition> _definitions = new(StringComparer.OrdinalIgnoreCase);
    private readonly Dictionary<string, MonsterCombatProfile> _compiledProfiles = new(StringComparer.OrdinalIgnoreCase);
    private readonly Dictionary<string, int[]> _depthStages = new(StringComparer.OrdinalIgnoreCase);
    private readonly MonsterCombatOptions _source;

    public MonsterCombatCatalog(IOptions<MonsterCombatOptions> options, BattleStatusCatalog? statuses = null)
    {
        _source = Copy(options.Value);
        var content = Copy(_source);
        Statuses = statuses ?? new BattleStatusCatalog(Options.Create(_source));

        foreach (var skill in content.Skills)
        {
            if (string.IsNullOrWhiteSpace(skill.Code) || string.IsNullOrWhiteSpace(skill.Name) ||
                string.IsNullOrWhiteSpace(skill.Description) || skill.TargetType is not ("Self" or "Front" or "AllAlive" or "RandomAlive") ||
                skill.DamagePowerPercent < 0 || skill.CooldownRounds < 0 || skill.InitialCooldownRounds < 0 ||
                skill.SelfHpBelowPercent is < 1 or > 100 ||
                skill.RoomRoundAtLeast is < 1 or > 250 || skill.ForcedPriority is < 0 or > 100 ||
                skill.DangerLevel is not ("Normal" or "Dangerous" or "Deadly") ||
                (skill.Effects is null ? skill.DamagePowerPercent == 0 && skill.Statuses.Count == 0 :
                    skill.DamagePowerPercent != 0 || skill.Statuses.Count != 0 || skill.Effects.Count == 0 ||
                    skill.Effects.Any(effect => !ValidEffect(effect, skill.TargetType))) ||
                skill.Statuses.Any(status => status.DurationRounds <= 0 || Statuses.Find(status.StatusCode) is null) ||
                !_skills.TryAdd(skill.Code, skill))
                throw new InvalidOperationException($"Invalid monster skill configuration: {skill.Code}");
        }

        foreach (var (code, profile) in content.Profiles)
        {
            if (string.IsNullOrWhiteSpace(code) || profile.SkillUseChancePercent is < 0 or > 100 ||
                profile.Skills.Any(skill => skill.Weight <= 0 || !_skills.ContainsKey(skill.Code)) ||
                profile.Skills.Select(skill => skill.Code).Distinct(StringComparer.OrdinalIgnoreCase).Count() != profile.Skills.Count ||
                !ValidFireCore(profile) || !ValidDeepCold(profile) || !ValidEarthArmor(profile) || !ValidStaticField(profile) ||
                !ValidReflectionMirror(profile) || !ValidPlaguePoison(profile) ||
                !_profiles.TryAdd(code, profile))
                throw new InvalidOperationException($"Invalid monster combat profile: {code}");
        }

        foreach (var (code, stages) in _source.DepthProgressions)
        {
            if (string.IsNullOrWhiteSpace(code) || stages.Count == 0 ||
                stages.Select(stage => stage.Depth).Distinct().Count() != stages.Count ||
                stages.Any(stage => stage.Depth is < 2 or > 100 ||
                    stage.ReplacementProfileCode is not null && !_profiles.ContainsKey(stage.ReplacementProfileCode) ||
                    stage.AddedSkills.Any(skill => skill.Weight <= 0 || !_skills.ContainsKey(skill.Code))))
                throw new InvalidOperationException($"Invalid monster depth progression: {code}");
        }
        foreach (var (baseCode, baseProfile) in _profiles.ToArray())
        {
            if (baseProfile.DepthProgressionCode is null) continue;
            if (!_source.DepthProgressions.TryGetValue(baseProfile.DepthProgressionCode, out var progression))
                throw new InvalidOperationException($"Unknown monster depth progression for {baseCode}: {baseProfile.DepthProgressionCode}");
            var stages = progression.OrderBy(stage => stage.Depth).ToArray();
            _depthStages.Add(baseCode, stages.Select(stage => stage.Depth).ToArray());
            var current = CopyProfile(baseProfile);
            foreach (var stage in stages)
            {
                if (stage.ReplacementProfileCode is not null)
                    current = CopyProfile(_source.Profiles[stage.ReplacementProfileCode]);
                current.Skills.AddRange(stage.AddedSkills.Select(skill => new MonsterProfileSkillOptions
                    { Code = skill.Code, Weight = skill.Weight }));
                if (current.Skills.Select(skill => skill.Code).Distinct(StringComparer.OrdinalIgnoreCase).Count() != current.Skills.Count)
                    throw new InvalidOperationException($"Duplicate skill in monster depth progression: {baseCode}, LV{stage.Depth}");
                var code = DepthProfileCode(baseCode, stage.Depth);
                if (!_profiles.TryAdd(code, CopyProfile(current)))
                    throw new InvalidOperationException($"Reserved depth profile code: {code}");
            }
        }
        foreach (var skill in _skills.Values)
            _definitions.Add(skill.Code, MonsterSkillDefinition.Compile(skill));
        foreach (var (code, profile) in _profiles)
            _compiledProfiles.Add(code, new(profile.SkillUseChancePercent,
                profile.Skills.Select(skill => new MonsterProfileSkill(skill.Code, skill.Weight)).ToImmutableArray(),
                profile.UseEncounterLocalSkillClock));
    }

    private bool ValidEffect(CombatSkillEffectOptions effect, string intentTarget)
    {
        if (effect.Target is not ("Self" or "Front" or "AllAlive" or "RandomAlive") ||
            effect.Target != "Self" && effect.Target != intentTarget || effect.Power < 0 ||
            effect.AttackPowerPercent is < 0 or > 1000 || effect.HealMaxHpPercent is < 0 or > 100) return false;
        return effect.Type switch
        {
            "Damage" => effect.Target != "Self" && (effect.Power > 0 || effect.AttackPowerPercent > 0),
            "Heal" => effect.Target == "Self" && (effect.Power > 0 || effect.HealMaxHpPercent > 0),
            "Guard" => effect.Target == "Self" && effect.Power is > 0 and <= 100,
            "Cleanse" => effect.Target == "Self",
            "Dispel" => effect.Target != "Self",
            "ApplyStatus" => effect.DurationRounds > 0 && Statuses.Find(effect.StatusCode) is not null,
            _ => false
        };
    }

    private bool ValidFireCore(MonsterCombatProfileOptions profile)
    {
        if (profile.FireCore is not { } core) return true;
        var validTrigger = core.TriggerHpPercent is { } hp
            ? hp is >= 1 and <= 99 && core.FirstActivationRound == 0 && core.CycleRounds == 0
            : core.FirstActivationRound is >= 1 and <= 250 && core.CycleRounds is >= 1 and <= 250 &&
                core.CycleRounds > core.WindowRounds + core.RewardRounds;
        var validLink = core.ExtraTargetCount == 0
            ? core.ExtraAttackPowerPercent == 0 && string.IsNullOrEmpty(core.LinkedSkillCode)
            : core.ExtraTargetCount is >= 1 and <= 4 && core.ExtraAttackPowerPercent is > 0 and <= 1000 &&
                profile.Skills.Any(skill => skill.Code == core.LinkedSkillCode) &&
                _skills.TryGetValue(core.LinkedSkillCode, out var linked) && linked.TargetType == "Front";
        return validTrigger && validLink &&
            core.WindowRounds is >= 1 and <= 10 && core.RewardRounds is >= 1 and <= 10 &&
            core.BreakWaterDamagePercent is > 0 and <= 100 &&
            Statuses.Find(core.HeatingStatusCode) is { EffectType: "AttackPercent", IsDispellable: false, IsPositive: true,
                Lifetime: Game.Shared.Enums.BattleStatusLifetime.Rounds, ValuePerStack: > 0 } &&
            Statuses.Find(core.RewardStatusCode) is { EffectType: "DamageTakenPercent", IsDispellable: false, IsPositive: false,
                Lifetime: Game.Shared.Enums.BattleStatusLifetime.Rounds, ValuePerStack: > 0 };
    }

    private bool ValidPlaguePoison(MonsterCombatProfileOptions profile)
    {
        if (profile.PlaguePoison is not { } poison) return true;
        var codes = new[] { poison.PoisonStatusCode, poison.TargetStatusCode, poison.TickUsedStatusCode, poison.RewardStatusCode };
        return profile.FireCore is null && profile.DeepCold is null && profile.EarthArmor is null &&
            profile.StaticField is null && profile.ReflectionMirror is null && poison.TriggerHpPercent is >= 1 and <= 99 &&
            poison.WindowRounds is >= 2 and <= 10 && poison.RewardRounds is >= 1 and <= 10 &&
            poison.BreakLightDamagePercent is > 0 and <= 100 && poison.AttackPercentPerStack is > 0 and <= 1000 &&
            codes.All(code => !string.IsNullOrWhiteSpace(code)) && codes.Distinct(StringComparer.OrdinalIgnoreCase).Count() == codes.Length &&
            Statuses.Find(poison.PoisonStatusCode) is { EffectType: "DamageOverTime", IsPositive: false, IsDispellable: true,
                IsHidden: false, Lifetime: Game.Shared.Enums.BattleStatusLifetime.Rounds,
                Mechanic: Game.Shared.Enums.BattleStatusMechanic.PlaguePoison,
                CounterKind: Game.Shared.Enums.BattleStatusCounterKind.Stacks, InitialStacks: 1 } dot &&
            dot.MaxStacks == (poison.LethalStacks > 0 ? poison.LethalStacks : poison.WindowRounds) && ValidPlagueLink(poison, codes) &&
            ValidColdMarker(poison.TargetStatusCode, Game.Shared.Enums.BattleStatusLifetime.Encounter) &&
            ValidColdMarker(poison.TickUsedStatusCode, Game.Shared.Enums.BattleStatusLifetime.Encounter) &&
            Statuses.Find(poison.TickUsedStatusCode)!.MaxStacks >= poison.WindowRounds &&
            Statuses.Find(poison.RewardStatusCode) is { EffectType: "ReductionPercent", ValuePerStack: > 0 and < 100,
                IsPositive: true, IsDispellable: false, IsHidden: false, MaxStacks: 1,
                Lifetime: Game.Shared.Enums.BattleStatusLifetime.Rounds } &&
            poison.BasicPoisonStatusCodes.Count > 0 && poison.BasicPoisonStatusCodes.Distinct(StringComparer.OrdinalIgnoreCase).Count() == poison.BasicPoisonStatusCodes.Count &&
            poison.BasicPoisonStatusCodes.All(code => !codes.Contains(code) &&
                Statuses.Find(code) is { EffectType: "DamageOverTime", IsPositive: false, IsDispellable: true,
                    Mechanic: Game.Shared.Enums.BattleStatusMechanic.None });
    }

    private bool ValidPlagueLink(PlaguePoisonOptions poison, string[] codes) => poison.ErosionStartStacks == 0
        ? poison.ErosionPercentPerStack == 0 && poison.LethalStacks == 0 && string.IsNullOrEmpty(poison.ErosionStatusCode)
        : poison.ErosionStartStacks >= 2 && poison.ErosionStartStacks <= poison.WindowRounds &&
            poison.LethalStacks == poison.WindowRounds + 1 && poison.ErosionPercentPerStack > 0 &&
            poison.ErosionPercentPerStack * (poison.WindowRounds - poison.ErosionStartStacks + 1) < 100 &&
            !codes.Contains(poison.ErosionStatusCode, StringComparer.OrdinalIgnoreCase) &&
            !poison.BasicPoisonStatusCodes.Contains(poison.ErosionStatusCode, StringComparer.OrdinalIgnoreCase) &&
            Statuses.Find(poison.ErosionStatusCode) is { EffectType: "None", IsPositive: false, IsDispellable: false,
                IsHidden: false, Lifetime: Game.Shared.Enums.BattleStatusLifetime.Encounter,
                Mechanic: Game.Shared.Enums.BattleStatusMechanic.PlagueErosion,
                CounterKind: Game.Shared.Enums.BattleStatusCounterKind.Stacks, InitialStacks: 1 } erosion &&
            erosion.MaxStacks == poison.WindowRounds - poison.ErosionStartStacks + 1;

    private bool ValidDeepCold(MonsterCombatProfileOptions profile)
    {
        if (profile.DeepCold is not { } cold) return true;
        var validTrigger = cold.TriggerHpPercent is { } hp
            ? hp is >= 1 and <= 99 && cold.FirstActivationRound == 0 && cold.CycleRounds == 0
            : cold.FirstActivationRound is >= 1 and <= 250 && cold.CycleRounds is >= 1 and <= 250 &&
                cold.CycleRounds > cold.WindowRounds + cold.RewardRounds;
        var codes = new[] { cold.ColdStatusCode, cold.FieldStatusCode, cold.WarmStatusCode,
            cold.PendingStatusCode, cold.ClearedStatusCode, cold.MeltUsedStatusCode };
        return profile.FireCore is null && validTrigger && Enum.IsDefined(cold.RemovalElement) &&
            cold.WindowRounds is >= 1 and <= 10 && cold.RewardRounds is >= 1 and <= 10 &&
            cold.InitialStacks is >= 1 and <= 10 && ValidColdGrowth(cold, codes) &&
            codes.Distinct(StringComparer.OrdinalIgnoreCase).Count() == codes.Length &&
            Statuses.Find(cold.ColdStatusCode) is { EffectType: "AttackPercent", ValuePerStack: < 0, IsPositive: false,
                IsDispellable: true, Lifetime: Game.Shared.Enums.BattleStatusLifetime.Rounds } status &&
            status.MaxStacks >= cold.InitialStacks && status.InitialStacks == cold.InitialStacks &&
            Statuses.Find(cold.FieldStatusCode) is { EffectType: "None", IsPositive: true, IsDispellable: false,
                Lifetime: Game.Shared.Enums.BattleStatusLifetime.Rounds, IsHidden: false } &&
            Statuses.Find(cold.WarmStatusCode) is { EffectType: "DamageDealtPercent", ValuePerStack: > 0 and <= 100,
                IsPositive: true, IsDispellable: false, Lifetime: Game.Shared.Enums.BattleStatusLifetime.Rounds, IsHidden: false } &&
            ValidColdMarker(cold.PendingStatusCode, Game.Shared.Enums.BattleStatusLifetime.Rounds) &&
            ValidColdMarker(cold.ClearedStatusCode, Game.Shared.Enums.BattleStatusLifetime.Encounter) &&
            ValidColdMarker(cold.MeltUsedStatusCode, Game.Shared.Enums.BattleStatusLifetime.CurrentRound) &&
            cold.BasicColdStatusCodes.Count > 0 && cold.BasicColdStatusCodes.Distinct().Count() == cold.BasicColdStatusCodes.Count &&
            cold.BasicColdStatusCodes.All(code => !codes.Contains(code) &&
                Statuses.Find(code) is { EffectType: "AttackPercent", ValuePerStack: < 0, IsPositive: false });
    }

    private bool ValidEarthArmor(MonsterCombatProfileOptions profile)
    {
        if (profile.EarthArmor is not { } armor) return true;
        var validTrigger = armor.TriggerHpPercent is { } hp
            ? hp is >= 1 and <= 99 && armor.FirstActivationRound == 0 && armor.CycleRounds == 0
            : armor.FirstActivationRound is >= 1 and <= 250 && armor.CycleRounds is >= 1 and <= 250 &&
                armor.CycleRounds >= armor.WindowRounds + armor.RewardRounds;
        return profile.FireCore is null && profile.DeepCold is null &&
            validTrigger &&
            armor.WindowRounds is >= 1 and <= 10 && armor.RewardRounds is >= 1 and <= 10 &&
            armor.BreakWindDamagePercent is > 0 and <= 100 &&
            !string.Equals(armor.ArmorStatusCode, armor.RewardStatusCode, StringComparison.OrdinalIgnoreCase) &&
            Statuses.Find(armor.ArmorStatusCode) is { EffectType: "ReductionPercent", IsDispellable: false,
                IsPositive: true, MaxStacks: 1, Lifetime: Game.Shared.Enums.BattleStatusLifetime.Rounds,
                ValuePerStack: > 0 and < 100 } &&
            Statuses.Find(armor.RewardStatusCode) is { EffectType: "DamageTakenPercent", IsDispellable: false,
                IsPositive: false, MaxStacks: 1, Lifetime: Game.Shared.Enums.BattleStatusLifetime.Rounds,
                ValuePerStack: > 0 and <= 100 } && ValidEarthResonance(armor);
    }

    private bool ValidStaticField(MonsterCombatProfileOptions profile)
    {
        if (profile.StaticField is not { } field) return true;
        var validTrigger = field.TriggerHpPercent is { } hp
            ? hp is >= 1 and <= 99 && field.FirstActivationRound == 0 && field.CycleRounds == 0
            : field.FirstActivationRound is >= 1 and <= 250 && field.CycleRounds is >= 1 and <= 250 &&
                field.CycleRounds >= field.WindowRounds + field.RewardRounds;
        var codes = new[] { field.StaticStatusCode, field.HitUsedStatusCode, field.GrowthUsedStatusCode, field.RewardStatusCode };
        return profile.FireCore is null && profile.DeepCold is null && profile.EarthArmor is null &&
            validTrigger && Enum.IsDefined(field.RemovalElement) &&
            field.WindowRounds is >= 2 and <= 10 && field.RewardRounds is >= 1 and <= 10 &&
            field.GrowthRounds > 0 && field.GrowthRounds < field.WindowRounds &&
            field.GrowthStacksPerRound is >= 1 and <= 10 && field.InitialStacks is >= 1 and <= 10 &&
            field.SkillDamagePercentPerStack is > 0 and <= 100 &&
            codes.Distinct(StringComparer.OrdinalIgnoreCase).Count() == codes.Length &&
            profile.Skills.Any(s => s.Code == field.AmplifiedSkillCode) &&
            _skills.TryGetValue(field.AmplifiedSkillCode, out var linked) && linked.TargetType == "AllAlive" &&
            linked.DamagePowerPercent > 0 &&
            Statuses.Find(field.StaticStatusCode) is { EffectType: "None", IsPositive: true, IsDispellable: false,
                IsHidden: false, Lifetime: Game.Shared.Enums.BattleStatusLifetime.Rounds,
                CounterKind: Game.Shared.Enums.BattleStatusCounterKind.Stacks } counter &&
            counter.MaxStacks >= field.InitialStacks && counter.InitialStacks == field.InitialStacks && ValidStaticThunder(profile, field, counter.MaxStacks) &&
            ValidColdMarker(field.HitUsedStatusCode, Game.Shared.Enums.BattleStatusLifetime.CurrentRound) &&
            ValidColdMarker(field.GrowthUsedStatusCode, Game.Shared.Enums.BattleStatusLifetime.Encounter) &&
            Statuses.Find(field.GrowthUsedStatusCode)!.MaxStacks >= field.GrowthRounds &&
            Statuses.Find(field.RewardStatusCode) is { EffectType: "DamageTakenPercent", IsDispellable: false,
                IsPositive: false, IsHidden: false, MaxStacks: 1, Lifetime: Game.Shared.Enums.BattleStatusLifetime.Rounds,
                ValuePerStack: > 0 and <= 100 };
    }

    private bool ValidReflectionMirror(MonsterCombatProfileOptions profile)
    {
        if (profile.ReflectionMirror is not { } mirror) return true;
        var validTrigger = mirror.TriggerHpPercent is { } hp
            ? hp is >= 1 and <= 99 && mirror.FirstActivationRound == 0 && mirror.CycleRounds == 0
            : mirror.FirstActivationRound is >= 1 and <= 250 && mirror.CycleRounds is >= 1 and <= 250 &&
                mirror.CycleRounds >= mirror.WindowRounds + mirror.RewardRounds;
        var codes = new[] { mirror.MirrorStatusCode, mirror.HitUsedStatusCode, mirror.BudgetStatusCode, mirror.RewardStatusCode };
        return profile.FireCore is null && profile.DeepCold is null && profile.EarthArmor is null && profile.StaticField is null &&
            validTrigger && mirror.WindowRounds is >= 1 and <= 10 &&
            mirror.InitialStacks is >= 1 and <= 10 && Enum.IsDefined(mirror.RemovalElement) &&
            mirror.ReflectPercentPerStack is > 0 and <= 100 && mirror.ReflectGrowthPercentPerStack is >= 0 and <= 100 &&
            mirror.MaxHpCapPercentPerStack is > 0 and <= 100 && mirror.MaxHpCapGrowthPercentPerStack is >= 0 and <= 100 &&
            (mirror.ReflectPercentPerStack + mirror.GrowthRounds * mirror.ReflectGrowthPercentPerStack) * mirror.InitialStacks <= 100 &&
            (mirror.MaxHpCapPercentPerStack + mirror.GrowthRounds * mirror.MaxHpCapGrowthPercentPerStack) * mirror.InitialStacks <= 100 &&
            ValidMirrorAmplification(mirror, codes) &&
            mirror.RewardRounds is >= 1 and <= 10 && codes.Distinct(StringComparer.OrdinalIgnoreCase).Count() == codes.Length &&
            Statuses.Find(mirror.MirrorStatusCode) is { EffectType: "None", IsPositive: true, IsDispellable: true,
                IsHidden: false, Lifetime: Game.Shared.Enums.BattleStatusLifetime.Rounds,
                CounterKind: Game.Shared.Enums.BattleStatusCounterKind.Stacks } counter &&
            counter.InitialStacks == mirror.InitialStacks && counter.MaxStacks == mirror.InitialStacks &&
            ValidColdMarker(mirror.HitUsedStatusCode, Game.Shared.Enums.BattleStatusLifetime.CurrentRound) &&
            ValidColdMarker(mirror.BudgetStatusCode, Game.Shared.Enums.BattleStatusLifetime.CurrentRound) &&
            Statuses.Find(mirror.RewardStatusCode) is { EffectType: "DamageTakenPercent", ValuePerStack: > 0 and <= 100,
                IsPositive: false, IsDispellable: false, IsHidden: false, MaxStacks: 1,
                Lifetime: Game.Shared.Enums.BattleStatusLifetime.Rounds };
    }

    private bool ValidMirrorAmplification(ReflectionMirrorOptions mirror, string[] codes) =>
        mirror.GrowthRounds == 0
            ? mirror.ReflectGrowthPercentPerStack == 0 && mirror.MaxHpCapGrowthPercentPerStack == 0 &&
              string.IsNullOrEmpty(mirror.AmplificationStatusCode)
            : mirror.GrowthRounds > 0 && mirror.GrowthRounds < mirror.WindowRounds &&
              mirror.ReflectGrowthPercentPerStack > 0 && mirror.MaxHpCapGrowthPercentPerStack > 0 &&
              !codes.Contains(mirror.AmplificationStatusCode, StringComparer.OrdinalIgnoreCase) &&
              Statuses.Find(mirror.AmplificationStatusCode) is { EffectType: "None", IsPositive: true, IsDispellable: false,
                  IsHidden: false, InitialStacks: 1, CounterKind: Game.Shared.Enums.BattleStatusCounterKind.Stacks,
                  Lifetime: Game.Shared.Enums.BattleStatusLifetime.Rounds } amplifier && amplifier.MaxStacks == mirror.GrowthRounds;

    private bool ValidStaticThunder(MonsterCombatProfileOptions profile, StaticFieldOptions field, int maxStacks) =>
        field.ThunderAtStacks == 0
            ? string.IsNullOrEmpty(field.ThunderSkillCode) && string.IsNullOrEmpty(field.ThunderPendingStatusCode)
            : field.ThunderAtStacks == maxStacks && field.ThunderAtStacks > field.InitialStacks &&
              profile.Skills.Any(s => s.Code == field.ThunderSkillCode) &&
              _skills.TryGetValue(field.ThunderSkillCode, out var thunder) && thunder.TargetType == "AllAlive" &&
              thunder.DamagePowerPercent > 0 && !thunder.IsInterruptible && thunder.DangerLevel == "Deadly" &&
              !new[] { field.StaticStatusCode, field.HitUsedStatusCode, field.GrowthUsedStatusCode, field.RewardStatusCode }
                  .Contains(field.ThunderPendingStatusCode, StringComparer.OrdinalIgnoreCase) &&
              Statuses.Find(field.ThunderPendingStatusCode) is { EffectType: "None", IsPositive: true,
                  IsDispellable: false, IsHidden: false, MaxStacks: 1, Lifetime: Game.Shared.Enums.BattleStatusLifetime.Rounds };

    private bool ValidEarthResonance(EarthArmorOptions armor) =>
        string.IsNullOrEmpty(armor.ResonanceStatusCode) ||
        !string.Equals(armor.ResonanceStatusCode, armor.ArmorStatusCode, StringComparison.OrdinalIgnoreCase) &&
        !string.Equals(armor.ResonanceStatusCode, armor.RewardStatusCode, StringComparison.OrdinalIgnoreCase) &&
        Statuses.Find(armor.ResonanceStatusCode) is { EffectType: "AttackPercent", IsPositive: true,
            IsDispellable: false, IsHidden: false, InitialStacks: 1, ValuePerStack: > 0 and <= 100,
            CounterKind: Game.Shared.Enums.BattleStatusCounterKind.Stacks,
            Lifetime: Game.Shared.Enums.BattleStatusLifetime.Encounter };

    private bool ValidColdMarker(string code, Game.Shared.Enums.BattleStatusLifetime lifetime) =>
        Statuses.Find(code) is { EffectType: "None", IsPositive: true, IsDispellable: false, IsHidden: true } marker &&
        marker.Lifetime == lifetime;

    private bool ValidColdGrowth(DeepColdOptions cold, string[] baseCodes)
    {
        var codes = new[] { cold.FreezeStatusCode, cold.FreezePendingStatusCode, cold.FreezeUsedStatusCode, cold.GrowthUsedStatusCode };
        if (cold.GrowthStacksPerRound == 0)
            return cold.FreezeAtStacks == 0 && codes.All(string.IsNullOrEmpty);
        return cold.GrowthStacksPerRound is >= 1 and <= 10 && cold.FreezeAtStacks > cold.InitialStacks &&
            Statuses.Find(cold.ColdStatusCode)?.MaxStacks == cold.FreezeAtStacks &&
            codes.Concat(baseCodes).Distinct(StringComparer.OrdinalIgnoreCase).Count() == codes.Length + baseCodes.Length &&
            Statuses.Find(cold.FreezeStatusCode) is { EffectType: "ActionBlocked", ValuePerStack: 1, MaxStacks: 1,
                IsPositive: false, IsDispellable: false, IsHidden: false, Lifetime: Game.Shared.Enums.BattleStatusLifetime.CurrentRound } &&
            ValidColdMarker(cold.FreezePendingStatusCode, Game.Shared.Enums.BattleStatusLifetime.Rounds) &&
            ValidColdMarker(cold.FreezeUsedStatusCode, Game.Shared.Enums.BattleStatusLifetime.Encounter) &&
            ValidColdMarker(cold.GrowthUsedStatusCode, Game.Shared.Enums.BattleStatusLifetime.CurrentRound);
    }

    public string ResolveDepthProfile(string baseProfileCode, int depth)
    {
        if (depth <= 1 || !_depthStages.TryGetValue(baseProfileCode, out var stages)) return baseProfileCode;
        var stage = stages.LastOrDefault(level => level <= depth);
        return stage == 0 ? baseProfileCode : DepthProfileCode(baseProfileCode, stage);
    }

    public IReadOnlyList<string> GetAddedMechanics(string baseProfileCode, int depth)
    {
        if (!_profiles.TryGetValue(baseProfileCode, out var original)) return [];
        var resolved = ResolveProfile(ResolveDepthProfile(baseProfileCode, depth));
        var originalCodes = original.Skills.Select(skill => skill.Code).ToHashSet(StringComparer.OrdinalIgnoreCase);
        var names = resolved is null ? [] : resolved.Skills.Where(skill => !originalCodes.Contains(skill.Code) &&
                skill.Code != FindProfile(ResolveDepthProfile(baseProfileCode, depth))?.StaticField?.ThunderSkillCode)
            .Select(skill => _definitions[skill.Code].Name).Distinct().ToList();
        if (FindProfile(ResolveDepthProfile(baseProfileCode, depth))?.FireCore is { } core)
        {
            names.Add(Statuses.Find(core.HeatingStatusCode)!.Name);
            if (core.ExtraTargetCount > 0) names.Add("熔火扩散");
            if (core.TriggerHpPercent is null) names.Add("火山循环");
        }
        if (FindProfile(ResolveDepthProfile(baseProfileCode, depth))?.DeepCold is { } cold)
        {
            names.Add(Statuses.Find(cold.ColdStatusCode)!.Name);
            if (cold.FreezeAtStacks > 0) names.Add(Statuses.Find(cold.FreezeStatusCode)!.Name);
            if (cold.TriggerHpPercent is null) names.Add("永冻循环");
        }
        if (FindProfile(ResolveDepthProfile(baseProfileCode, depth))?.EarthArmor is { } armor)
        {
            names.Add(Statuses.Find(armor.ArmorStatusCode)!.Name);
            if (!string.IsNullOrEmpty(armor.ResonanceStatusCode)) names.Add(Statuses.Find(armor.ResonanceStatusCode)!.Name);
            if (armor.TriggerHpPercent is null) names.Add("深岩循环");
        }
        if (FindProfile(ResolveDepthProfile(baseProfileCode, depth))?.StaticField is { } field)
        {
            names.Add("静电领域");
            if (field.ThunderAtStacks > 0) names.Add("雷暴共鸣");
            if (field.TriggerHpPercent is null) names.Add("风暴循环");
        }
        if (FindProfile(ResolveDepthProfile(baseProfileCode, depth))?.ReflectionMirror is { } mirror)
        {
            names.Add("琉辉反镜");
            if (mirror.GrowthRounds > 0) names.Add(Statuses.Find(mirror.AmplificationStatusCode)!.Name);
            if (mirror.TriggerHpPercent is null) names.Add("黎明循环");
        }
        if (FindProfile(ResolveDepthProfile(baseProfileCode, depth))?.PlaguePoison is { } poison)
        {
            names.Add(Statuses.Find(poison.PoisonStatusCode)!.Name);
            if (poison.ErosionStartStacks > 0) names.Add(Statuses.Find(poison.ErosionStatusCode)!.Name);
            if (poison.LethalStacks > 0) names.Add("腐巢死亡倒计时");
        }
        return names.Distinct().ToArray();
    }

    // Export authored declarations, never the generated profiles, so rebuilding cannot generate twice.
    public MonsterCombatOptions ExportOptions() => Copy(_source);

    private static MonsterCombatOptions Copy(MonsterCombatOptions source)
    {
        var copy = JsonSerializer.Deserialize<MonsterCombatOptions>(JsonSerializer.Serialize(source))!;
        copy.Profiles = new(copy.Profiles, StringComparer.OrdinalIgnoreCase);
        copy.DepthProgressions = new(copy.DepthProgressions, StringComparer.OrdinalIgnoreCase);
        return copy;
    }

    private static MonsterCombatProfileOptions CopyProfile(MonsterCombatProfileOptions source) => new()
    {
        SkillUseChancePercent = source.SkillUseChancePercent,
        UseEncounterLocalSkillClock = source.UseEncounterLocalSkillClock,
        FireCore = source.FireCore is null ? null : JsonSerializer.Deserialize<FireCoreOptions>(JsonSerializer.Serialize(source.FireCore)),
        DeepCold = source.DeepCold is null ? null : JsonSerializer.Deserialize<DeepColdOptions>(JsonSerializer.Serialize(source.DeepCold)),
        EarthArmor = source.EarthArmor is null ? null : JsonSerializer.Deserialize<EarthArmorOptions>(JsonSerializer.Serialize(source.EarthArmor)),
        StaticField = source.StaticField is null ? null : JsonSerializer.Deserialize<StaticFieldOptions>(JsonSerializer.Serialize(source.StaticField)),
        ReflectionMirror = source.ReflectionMirror is null ? null : JsonSerializer.Deserialize<ReflectionMirrorOptions>(JsonSerializer.Serialize(source.ReflectionMirror)),
        PlaguePoison = source.PlaguePoison is null ? null : JsonSerializer.Deserialize<PlaguePoisonOptions>(JsonSerializer.Serialize(source.PlaguePoison)),
        Skills = source.Skills.Select(skill => new MonsterProfileSkillOptions { Code = skill.Code, Weight = skill.Weight }).ToList()
    };

    private static string DepthProfileCode(string baseProfileCode, int depth) => $"{baseProfileCode}:depth-lv{depth}";

    public BattleStatusDefinition? FindStatus(string? code) => Statuses.Find(code);

    public MonsterSkillDefinition? ResolveSkill(string? code) =>
        code is not null && _definitions.TryGetValue(code, out var skill) ? skill : null;

    public MonsterCombatProfile? ResolveProfile(string? code) =>
        code is not null && _compiledProfiles.TryGetValue(code, out var profile) ? profile : null;

    public MonsterSkillOptions? FindSkill(string? code) =>
        code is not null && _skills.TryGetValue(code, out var skill) ? skill : null;

    public MonsterCombatProfileOptions? FindProfile(string? code) =>
        code is not null && _profiles.TryGetValue(code, out var profile) ? profile : null;
}

using Game.Server.Configuration;
using Game.Shared;
using Game.Shared.Dtos;
using Game.Shared.Enums;
using Game.Shared.Models;
using Microsoft.EntityFrameworkCore;

namespace Game.Server.Services;

public sealed partial class MonsterPhaseService
{
    public PlaguePoisonOptions? PlaguePoisonDefinition(Room room, Monster monster) =>
        (runRules?.CombatFor(room) ?? catalog).FindProfile(monster.CombatProfileCode)?.PlaguePoison;

    public static long RequiredLightDamage(Monster monster, PlaguePoisonOptions poison) =>
        (long)decimal.Ceiling(monster.MaxHp * poison.BreakLightDamagePercent / 100m);

    private async Task<IReadOnlyList<BattleParticipant>> PlaguePartyAsync(Room room,
        IReadOnlyList<BattleParticipant>? participants) => participants ??
        await (from slot in db.RoomSlots join character in db.Characters on slot.CharacterId equals character.Id
            where slot.RoomId == room.Id orderby slot.SlotIndex select new BattleParticipant(slot, character)).ToListAsync();

    private async Task<int?> PlagueTargetAsync(Room room, Monster monster, PlaguePoisonOptions poison) =>
        (await statuses.GetActiveAsync(room, "Monster", [monster.Id]))
            .FirstOrDefault(s => s.EffectCode == poison.TargetStatusCode && s.BoundTargetType == "Character")?.BoundTargetId;

    public async Task RefreshPlagueHealthAsync(Room room, Monster monster, IReadOnlyList<BattleParticipant> party)
    {
        if (PlaguePoisonDefinition(room, monster) is not { ErosionStartStacks: > 0 } poison) return;
        var effects = room.Status == RoomStatus.BattleOver || room.ClosedAtUtc.HasValue || monster.Hp <= 0 ? [] :
            await statuses.GetActiveAsync(room, "Character", party.Select(p => p.Character.Id).ToArray());
        foreach (var participant in party)
        {
            var erosion = effects.FirstOrDefault(e => e.TargetId == participant.Character.Id &&
                e.EffectCode == poison.ErosionStatusCode && e.BoundTargetId == monster.Id);
            participant.Character.BattleMaxHpLimit = erosion?.MagnitudeSnapshot is { } original
                ? Math.Max(1, (int)decimal.Floor(original * (1m - poison.ErosionPercentPerStack * erosion.Stacks / 100m))) : null;
        }
    }

    private async Task ClearPlagueErosionAsync(Room room, PlaguePoisonOptions poison, BattleParticipant target)
    {
        if (poison.ErosionStartStacks == 0) return;
        target.Character.BattleMaxHpLimit = null;
        await statuses.RemoveAsync(room, "Character", target.Character.Id, poison.ErosionStatusCode);
    }

    private async Task RemoveBossBasicPoisonAsync(Room room, Monster monster, PlaguePoisonOptions poison, int characterId)
    {
        var basic = (await statuses.GetActiveAsync(room, "Character", [characterId]))
            .Where(s => poison.BasicPoisonStatusCodes.Contains(s.EffectCode) &&
                s.SourceActorType == "Monster" && s.SourceActorId == monster.Id).ToList();
        foreach (var effect in basic)
            await statuses.RemoveAsync(room, "Character", characterId, effect.EffectCode);
    }

    private async Task BeginPlagueRoundAsync(Room room, Monster monster, PlaguePoisonOptions poison,
        List<string> logs, IReadOnlyList<BattleParticipant>? participants)
    {
        await EncounterSkillRoundAsync(room, monster);
        var state = (await FindAsync(room, monster))!;
        var party = await PlaguePartyAsync(room, participants);
        await RefreshPlagueHealthAsync(room, monster, party);
        if (monster.Hp <= 0) { await ClearPlagueAsync(room, monster, poison, state, party, removeReward: true); return; }
        if (state.LastPreparedRound == room.RoundNumber) return;
        state.LastPreparedRound = room.RoundNumber;
        if (state.RewardStartsAtRound is { } reward && reward <= room.RoundNumber)
        {
            var targetId = await PlagueTargetAsync(room, monster, poison);
            var target = party.FirstOrDefault(p => p.Character.Id == targetId);
            if (reward == room.RoundNumber && target is { Character.Hp: > 0 })
            {
                await RemoveBossBasicPoisonAsync(room, monster, poison, target.Character.Id);
                await statuses.ApplyAsync(room, "Character", target.Character.Id, poison.RewardStatusCode, poison.RewardRounds - 1,
                    logs, target.Character.Name, source: new("Monster", monster.Id, "plague-poison-reward"),
                    boundTargetType: "Monster", boundTargetId: monster.Id);
            }
            state.RewardStartsAtRound = null;
        }
        if (state.IsActive || state.ActivationCount > 0 || (long)monster.Hp * 100 > (long)monster.MaxHp * poison.TriggerHpPercent) return;
        var front = party.Where(p => p.Character.Hp > 0).OrderBy(p => p.Slot.SlotIndex).FirstOrDefault();
        if (front is null) return;
        state.IsActive = true;
        state.ActivationCount++;
        state.ElementDamage = 0;
        state.LastActivationRound = room.RoundNumber;
        state.ExpiresAfterRound = checked(room.RoundNumber + poison.WindowRounds - 1);
        var modifier = await statuses.ModifierAsync(room, "Monster", monster.Id, "AttackPercent");
        var unit = Math.Max(1, (int)Math.Min(int.MaxValue, decimal.Floor(monster.Attack *
            Math.Max(0, 1m + modifier / 100m) * poison.AttackPercentPerStack / 100m)));
        await statuses.ApplyAsync(room, "Monster", monster.Id, poison.TargetStatusCode, 0, [], "",
            source: new("Monster", monster.Id, "plague-poison-activation"),
            boundTargetType: "Character", boundTargetId: front.Character.Id,
            magnitudeSnapshot: poison.ErosionStartStacks > 0 ? TalentRules.EffectiveMaxHpWithoutBattleLimit(front.Character) : null);
        await RemoveBossBasicPoisonAsync(room, monster, poison, front.Character.Id);
        await statuses.ApplyAsync(room, "Character", front.Character.Id, poison.PoisonStatusCode, poison.WindowRounds - 1,
            logs, front.Character.Name, perTickValue: unit, source: new("Monster", monster.Id, "plague-poison-tick"),
            boundTargetType: "Monster", boundTargetId: monster.Id, counterCount: 1);
        logs.Add($"{monster.Name} 向 {front.Character.Name} 播下疫巢剧毒：从1层开始，每回合末毒伤后增加一层；{poison.WindowRounds}个完整回合内净化或累计 {RequiredLightDamage(monster, poison)} 点光属性直接伤害可解毒。");
        if (poison.LethalStacks > 0)
            logs.Add($"疫巢剧毒达到{poison.ErosionStartStacks}层开始侵蚀生命上限，达到{poison.LethalStacks}层时目标死亡；最后一个处理回合仍可净化或光伤解毒。");
    }

    private async Task ObservePlagueDamageAsync(BattleExecutionContext battle, PlaguePoisonOptions poison,
        ElementType? element, int damage)
    {
        if (element != ElementType.Light || damage <= 0 || battle.Monster.Hp <= 0 ||
            await FindAsync(battle.Room, battle.Monster) is not { IsActive: true } state ||
            state.ExpiresAfterRound < battle.Room.RoundNumber) return;
        var targetId = await PlagueTargetAsync(battle.Room, battle.Monster, poison);
        var target = battle.Party.FirstOrDefault(p => p.Character.Id == targetId);
        if (target is not { Character.Hp: > 0 }) return;
        state.ElementDamage += damage;
        if (state.ElementDamage >= RequiredLightDamage(battle.Monster, poison))
            await BreakPlagueAsync(battle, poison, state, target.Character.Id);
    }

    public async Task ObservePlagueCleanseAsync(BattleExecutionContext battle, int characterId, string code)
    {
        if (PlaguePoisonDefinition(battle.Room, battle.Monster) is not { } poison || code != poison.PoisonStatusCode ||
            battle.Monster.Hp <= 0 || await FindAsync(battle.Room, battle.Monster) is not { IsActive: true } state ||
            state.ExpiresAfterRound < battle.Room.RoundNumber ||
            await PlagueTargetAsync(battle.Room, battle.Monster, poison) != characterId ||
            battle.Party.All(p => p.Character.Id != characterId || p.Character.Hp <= 0) ||
            await statuses.HasAsync(battle.Room, "Character", characterId, poison.PoisonStatusCode)) return;
        await BreakPlagueAsync(battle, poison, state, characterId);
    }

    private async Task BreakPlagueAsync(BattleExecutionContext battle, PlaguePoisonOptions poison,
        BattleMonsterPhaseState state, int targetId)
    {
        state.IsActive = false;
        state.BreakCount++;
        state.LastBreakRound = battle.Room.RoundNumber;
        state.RewardStartsAtRound = checked(battle.Room.RoundNumber + 1);
        await statuses.RemoveAsync(battle.Room, "Character", targetId, poison.PoisonStatusCode);
        await ClearPlagueErosionAsync(battle.Room, poison, battle.Party.Single(p => p.Character.Id == targetId));
        await statuses.RemoveAsync(battle.Room, "Monster", battle.Monster.Id, poison.TickUsedStatusCode);
        battle.Logs.Add($"疫巢剧毒已被主动解除；目标从下一完整回合起获得{poison.RewardRounds}回合净蚀庇护，直接减伤并免疫该首领基础腐毒。");
    }

    public async Task<bool> SuppressBasicPoisonAsync(Room room, Monster monster, int characterId, string code)
    {
        if (PlaguePoisonDefinition(room, monster) is not { } poison || !poison.BasicPoisonStatusCodes.Contains(code) || monster.Hp <= 0) return false;
        return await statuses.HasAsync(room, "Character", characterId, poison.RewardStatusCode) ||
            await FindAsync(room, monster) is { IsActive: true } state && state.ExpiresAfterRound >= room.RoundNumber &&
            await PlagueTargetAsync(room, monster, poison) == characterId;
    }

    private async Task EndPlagueRoundAsync(Room room, Monster monster, PlaguePoisonOptions poison, List<string> logs,
        IReadOnlyList<BattleParticipant>? participants, IReadOnlyDictionary<int, OperationPotionBonuses>? operationBonuses)
    {
        if (await FindAsync(room, monster) is not { } state) return;
        var party = await PlaguePartyAsync(room, participants);
        var targetId = await PlagueTargetAsync(room, monster, poison);
        var target = party.FirstOrDefault(p => p.Character.Id == targetId);
        if (monster.Hp <= 0 || target is not { Character.Hp: > 0 })
        {
            await ClearPlagueAsync(room, monster, poison, state, party, removeReward: true);
            return;
        }
        if (!state.IsActive || state.LastActivationRound is not { } start) return;
        var phaseRound = room.RoundNumber - start + 1;
        if (await statuses.StacksAsync(room, "Monster", monster.Id, poison.TickUsedStatusCode) >= phaseRound) return;
        var dot = (await statuses.GetActiveAsync(room, "Character", [target.Character.Id]))
            .FirstOrDefault(s => s.EffectCode == poison.PoisonStatusCode && s.BoundTargetId == monster.Id);
        if (dot is null) { await ClearPlagueAsync(room, monster, poison, state, party, removeReward: false); return; }
        await statuses.SetCounterAsync(room, "Monster", monster.Id, poison.TickUsedStatusCode, phaseRound,
            boundTargetType: "Monster", boundTargetId: monster.Id);
        var taken = operationBonuses?.GetValueOrDefault(target.Character.Id).DamageTakenPercent ?? 0;
        var damage = Math.Max(1, (int)Math.Min(int.MaxValue, decimal.Floor((dot.PerTickValue ?? 1) *
            (decimal)dot.Stacks * Math.Max(0, 1m + taken / 100m))));
        var before = target.Character.Hp;
        target.Character.Hp = Math.Max(0, before - damage);
        using (statuses.Events.ActionScope(new BattleStatusSource("Monster", monster.Id, "plague-poison-tick"),
            "疫巢剧毒", BattleActionKind.Periodic))
            statuses.Events.Hp(room, BattleEventKind.Damage, null, BattleActor.ForCharacter(target), damage, before - target.Character.Hp, before);
        logs.Add($"{target.Character.Name} 受到{dot.Stacks}层疫巢剧毒，造成{damage}点伤害。");
        if (target.Character.Hp <= 0) { await ClearPlagueAsync(room, monster, poison, state, party, removeReward: true); return; }
        if (room.RoundNumber >= state.ExpiresAfterRound)
        {
            if (poison.LethalStacks > 0)
            {
                await statuses.IncreaseStacksAsync(room, "Character", target.Character.Id, poison.PoisonStatusCode, 1);
                var remaining = target.Character.Hp;
                target.Character.Hp = 0;
                using (statuses.Events.ActionScope(new BattleStatusSource("Monster", monster.Id, "plague-poison-lethal"),
                    "腐巢死亡倒计时", BattleActionKind.Mechanic))
                    statuses.Events.Hp(room, BattleEventKind.Damage, null, BattleActor.ForCharacter(target), remaining, remaining, remaining);
                state.LinkedHitCount++;
                await ClearPlagueAsync(room, monster, poison, state, party, removeReward: true);
                logs.Add($"{target.Character.Name} 的疫巢剧毒达到{poison.LethalStacks}层，腐巢死亡倒计时结束，目标死亡。");
                return;
            }
            state.ExpiryCount++;
            state.LastExpiryRound = room.RoundNumber;
            await ClearPlagueAsync(room, monster, poison, state, party, removeReward: false);
            logs.Add("疫巢剧毒自然消散，本次不发放净蚀庇护。");
            return;
        }
        // Keep the visible lifetime and original expiry; a zero-duration counter write would label it CurrentRound.
        await statuses.ApplyAsync(room, "Character", target.Character.Id, poison.PoisonStatusCode,
            state.ExpiresAfterRound - room.RoundNumber, [], "", perTickValue: dot.PerTickValue,
            source: new("Monster", monster.Id, "plague-poison-tick"), boundTargetType: "Monster", boundTargetId: monster.Id,
            counterCount: phaseRound + 1);
        if (poison.ErosionStartStacks > 0 && phaseRound + 1 >= poison.ErosionStartStacks)
        {
            var anchor = (await statuses.GetActiveAsync(room, "Monster", [monster.Id]))
                .Single(s => s.EffectCode == poison.TargetStatusCode);
            var erosionStacks = phaseRound + 2 - poison.ErosionStartStacks;
            await statuses.ApplyAsync(room, "Character", target.Character.Id, poison.ErosionStatusCode, 0, logs,
                target.Character.Name, source: new("Monster", monster.Id, "plague-poison-erosion"),
                boundTargetType: "Monster", boundTargetId: monster.Id, counterCount: erosionStacks,
                magnitudeSnapshot: anchor.MagnitudeSnapshot);
            await RefreshPlagueHealthAsync(room, monster, party);
            target.Character.Hp = Math.Min(target.Character.Hp, TalentRules.EffectiveMaxHp(target.Character));
            logs.Add($"{target.Character.Name} 的腐巢侵蚀使生命上限降低{erosionStacks * poison.ErosionPercentPerStack:0.##}%，主动解毒可恢复上限。");
        }
        logs.Add($"{target.Character.Name} 的疫巢剧毒积累至{phaseRound + 1}层。");
    }

    private async Task ClearPlagueAsync(Room room, Monster monster, PlaguePoisonOptions poison,
        BattleMonsterPhaseState state, IReadOnlyList<BattleParticipant> party, bool removeReward)
    {
        state.IsActive = false;
        state.RewardStartsAtRound = null;
        foreach (var participant in party)
        {
            await statuses.RemoveAsync(room, "Character", participant.Character.Id, poison.PoisonStatusCode);
            await ClearPlagueErosionAsync(room, poison, participant);
            if (removeReward) await statuses.RemoveAsync(room, "Character", participant.Character.Id, poison.RewardStatusCode);
        }
        await statuses.RemoveAsync(room, "Monster", monster.Id, poison.TargetStatusCode);
        await statuses.RemoveAsync(room, "Monster", monster.Id, poison.TickUsedStatusCode);
    }
}

using Game.Server.Configuration;
using Game.Server.Data;
using Game.Shared.Enums;
using Game.Shared.Models;
using Microsoft.EntityFrameworkCore;

namespace Game.Server.Services;

/// <summary>Persistent, encounter-local phases. The caller owns the round transaction.</summary>
public sealed partial class MonsterPhaseService(GameDbContext db, MonsterCombatCatalog catalog,
    BattleStatusService statuses, DungeonRunRulesService? runRules = null)
{
    public FireCoreOptions? Definition(Room room, Monster monster) =>
        (runRules?.CombatFor(room) ?? catalog).FindProfile(monster.CombatProfileCode)?.FireCore;

    private async Task<BattleMonsterPhaseState?> FindAsync(Room room, Monster monster) =>
        db.BattleMonsterPhaseStates.Local.FirstOrDefault(state => db.Entry(state).State != EntityState.Deleted &&
            state.RoomId == room.Id && state.RunSequence == room.RunSequence && state.MonsterId == monster.Id)
        ?? await db.BattleMonsterPhaseStates.SingleOrDefaultAsync(state => state.RoomId == room.Id &&
            state.RunSequence == room.RunSequence && state.MonsterId == monster.Id);

    // Zero-based skill clock. Reuse the persisted encounter state across intent previews/reloads.
    public async Task<int> EncounterSkillRoundAsync(Room room, Monster monster)
    {
        var state = await FindAsync(room, monster);
        if (state is null)
        {
            state = new BattleMonsterPhaseState
            {
                RoomId = room.Id, RunSequence = room.RunSequence, MonsterId = monster.Id,
                EncounterStartRound = room.RoundNumber,
                NextActivationRound = Definition(room, monster)?.FirstActivationRound ??
                    DeepColdDefinition(room, monster)?.FirstActivationRound ??
                    EarthArmorDefinition(room, monster)?.FirstActivationRound ??
                    StaticFieldDefinition(room, monster)?.FirstActivationRound ??
                    ReflectionMirrorDefinition(room, monster)?.FirstActivationRound ?? 0
            };
            db.BattleMonsterPhaseStates.Add(state);
        }
        return room.RoundNumber - state.EncounterStartRound;
    }

    public async Task BeginRoundAsync(Room room, Monster monster, List<string> logs,
        IReadOnlyList<BattleParticipant>? participants = null)
    {
        if (runRules is not null) await runRules.EnsureAsync(room);
        if (PlaguePoisonDefinition(room, monster) is { } poison)
        {
            await BeginPlagueRoundAsync(room, monster, poison, logs, participants);
            return;
        }
        if (ReflectionMirrorDefinition(room, monster) is { } mirror)
        {
            await BeginReflectionMirrorRoundAsync(room, monster, mirror, logs, participants);
            return;
        }
        if (StaticFieldDefinition(room, monster) is { } field)
        {
            await BeginStaticFieldRoundAsync(room, monster, field, logs);
            return;
        }
        if (EarthArmorDefinition(room, monster) is { } armor)
        {
            await BeginEarthArmorRoundAsync(room, monster, armor, logs);
            return;
        }
        if (DeepColdDefinition(room, monster) is { } cold)
        {
            await BeginDeepColdRoundAsync(room, monster, cold, logs, participants);
            return;
        }
        if (Definition(room, monster) is not { } core || monster.Hp <= 0) return;
        var state = await FindAsync(room, monster);
        if (state is null)
        {
            state = new BattleMonsterPhaseState
            {
                RoomId = room.Id, RunSequence = room.RunSequence, MonsterId = monster.Id,
                EncounterStartRound = room.RoundNumber, NextActivationRound = core.FirstActivationRound
            };
            db.BattleMonsterPhaseStates.Add(state);
        }
        if (state.LastPreparedRound == room.RoundNumber) return;
        state.LastPreparedRound = room.RoundNumber;
        if (state.RewardStartsAtRound == room.RoundNumber)
        {
            // Rounds statuses include the application round and then durationRounds more rounds.
            await statuses.ApplyAsync(room, "Monster", monster.Id, core.RewardStatusCode, core.RewardRounds - 1,
                logs, monster.Name, source: new("Monster", monster.Id, "fire-core-break"));
            state.RewardStartsAtRound = null;
        }
        var localRound = room.RoundNumber - state.EncounterStartRound + 1;
        if (!ShouldActivate(core, state, monster, localRound)) return;
        // Single HP-triggered phases never recur. Periodic phases keep their original cadence after a break.
        if (core.TriggerHpPercent is null)
            while (state.NextActivationRound <= localRound) state.NextActivationRound += core.CycleRounds;
        state.IsActive = true;
        state.WaterDamage = 0;
        state.ExpiresAfterRound = checked(room.RoundNumber + core.WindowRounds - 1);
        state.LastActivationRound = room.RoundNumber;
        state.ActivationCount++;
        await statuses.ApplyAsync(room, "Monster", monster.Id, core.HeatingStatusCode, core.WindowRounds - 1,
            logs, monster.Name, source: new("Monster", monster.Id, "fire-core-activation"));
        logs.Add($"{monster.Name} 开始蓄热：{core.WindowRounds}回合内累计造成 {RequiredDamage(monster, core)} 点水属性直接伤害可破核。");
    }

    public static long RequiredDamage(Monster monster, FireCoreOptions core) =>
        (long)decimal.Ceiling(monster.MaxHp * core.BreakWaterDamagePercent / 100m);

    public async Task ObserveDirectDamageAsync(BattleExecutionContext battle, ElementType? element, int actualDamage,
        int? sourceCharacterId = null)
    {
        if (PlaguePoisonDefinition(battle.Room, battle.Monster) is { } poison)
        {
            await ObservePlagueDamageAsync(battle, poison, element, actualDamage);
            return;
        }
        if (ReflectionMirrorDefinition(battle.Room, battle.Monster) is { } mirror)
        {
            await ObserveReflectionMirrorDamageAsync(battle, mirror, element, actualDamage, sourceCharacterId);
            return;
        }
        if (StaticFieldDefinition(battle.Room, battle.Monster) is { } field)
        {
            await ObserveStaticFieldDamageAsync(battle, field, element, actualDamage, sourceCharacterId);
            return;
        }
        if (EarthArmorDefinition(battle.Room, battle.Monster) is { } armor)
        {
            await ObserveEarthArmorDamageAsync(battle, armor, element, actualDamage);
            return;
        }
        if (sourceCharacterId.HasValue && element.HasValue && actualDamage > 0)
            await MeltDeepColdAsync(battle, sourceCharacterId.Value, element.Value);
        if (element != ElementType.Water || actualDamage <= 0 || Definition(battle.Room, battle.Monster) is not { } core) return;
        var state = await FindAsync(battle.Room, battle.Monster);
        if (state is null || !state.IsActive || state.ExpiresAfterRound < battle.Room.RoundNumber) return;
        state.WaterDamage += actualDamage;
        if (state.WaterDamage < RequiredDamage(battle.Monster, core)) return;
        state.IsActive = false;
        state.BreakCount++;
        state.LastBreakRound = battle.Room.RoundNumber;
        state.RewardStartsAtRound = checked(battle.Room.RoundNumber + 1);
        await statuses.RemoveAsync(battle.Room, "Monster", battle.Monster.Id, core.HeatingStatusCode);
        var removed = core.ExtraTargetCount > 0 ? "蓄热与扩散" : "蓄热";
        battle.Logs.Add($"{battle.Monster.Name} 的熔岩核心被击破，{removed}立即解除；接下来完整{core.RewardRounds}回合获得破核增伤窗口。");
    }

    public async Task<bool> IsHeatedAsync(Room room, Monster monster) =>
        Definition(room, monster) is not null && await FindAsync(room, monster) is { IsActive: true } state &&
        state.ExpiresAfterRound >= room.RoundNumber;

    public async Task<bool> WillBeHeatedAsync(Room room, Monster monster)
    {
        if (monster.Hp <= 0 || Definition(room, monster) is not { } core || await FindAsync(room, monster) is not { } state) return false;
        return state.IsActive && state.ExpiresAfterRound >= room.RoundNumber ||
            ShouldActivate(core, state, monster, room.RoundNumber - state.EncounterStartRound + 1);
    }

    private static bool ShouldActivate(FireCoreOptions core, BattleMonsterPhaseState state, Monster monster, int localRound) =>
        core.TriggerHpPercent is { } hp
            ? state.ActivationCount == 0 && (long)monster.Hp * 100 <= (long)monster.MaxHp * hp
            : localRound >= state.NextActivationRound;

    public async Task RecordLinkedHitAsync(Room room, Monster monster)
    {
        if (await FindAsync(room, monster) is { } state) state.LinkedHitCount++;
    }

    public async Task EndRoundAsync(Room room, Monster monster, List<string> logs,
        IReadOnlyList<BattleParticipant>? participants = null,
        IReadOnlyDictionary<int, OperationPotionBonuses>? operationBonuses = null)
    {
        if (PlaguePoisonDefinition(room, monster) is { } poison)
        {
            await EndPlagueRoundAsync(room, monster, poison, logs, participants, operationBonuses);
            return;
        }
        if (ReflectionMirrorDefinition(room, monster) is { } mirror)
        {
            await EndReflectionMirrorRoundAsync(room, monster, mirror, logs);
            return;
        }
        if (StaticFieldDefinition(room, monster) is { } field)
        {
            await EndStaticFieldRoundAsync(room, monster, field, logs);
            return;
        }
        if (EarthArmorDefinition(room, monster) is { } armor)
        {
            await EndEarthArmorRoundAsync(room, monster, armor, logs);
            return;
        }
        if (DeepColdDefinition(room, monster) is { } cold)
        {
            await EndDeepColdRoundAsync(room, monster, cold, logs);
            return;
        }
        if (Definition(room, monster) is not { } core || await FindAsync(room, monster) is not { IsActive: true } state) return;
        if (monster.Hp <= 0) { state.IsActive = false; return; }
        if (room.RoundNumber < state.ExpiresAfterRound) return;
        state.IsActive = false;
        state.ExpiryCount++;
        state.LastExpiryRound = room.RoundNumber;
        await statuses.RemoveAsync(room, "Monster", monster.Id, core.HeatingStatusCode);
        logs.Add($"{monster.Name} 的蓄热结束，恢复常态。");
    }

    public async Task ResetRoomAsync(int roomId)
    {
        var states = await db.BattleMonsterPhaseStates.Where(state => state.RoomId == roomId).ToListAsync();
        db.BattleMonsterPhaseStates.RemoveRange(states.Concat(db.BattleMonsterPhaseStates.Local
            .Where(state => state.RoomId == roomId)).Distinct().ToList());
    }
}

