const basic='dark-deep-lv1-poison',plague='dark-deep-lv4-plague',erosion='dark-deep-lv3-erosion',reward='dark-deep-lv2-sanctuary',boss='monster:5:1';
const definitions=new Map(cfg.MonsterCombat.StatusEffects.map(s=>[s.Code,s]));
